package com.cryptoloan.notification.adapters.out.persistence;import com.cryptoloan.notification.domain.model.Notification;import com.cryptoloan.notification.domain.port.out.NotificationPorts.Repository;import java.util.List;import org.springframework.stereotype.Component;@Component class NotificationRepositoryAdapter implements Repository{private final SpringDataNotificationRepository repo;NotificationRepositoryAdapter(SpringDataNotificationRepository repo){this.repo=repo;}public Notification save(Notification n){NotificationJpaEntity e=new NotificationJpaEntity();e.id=n.id();e.recipient=n.recipient();e.type=n.type();e.subject=n.subject();e.message=n.message();e.loanId=n.loanId();e.status=n.status();e.error=n.error();e.createdAt=n.createdAt();return domain(repo.save(e));}public List<Notification>findForRecipient(String email){return repo.findByRecipientOrderByCreatedAtDesc(email).stream().map(this::domain).toList();}private Notification domain(NotificationJpaEntity e){return new Notification(e.id,e.recipient,e.type,e.subject,e.message,e.loanId,e.status,e.error,e.createdAt);}}

